command:
install -d -m 0750 /var/log/remote-app
install -m 0640 /dev/null /var/log/remote-app/node1-local0.log
install -m 0640 /dev/null /var/log/remote-app/node2-local0.log
install -m 0640 /dev/null /var/log/remote-app/node3-local0.log
restorecon -RF /var/log/remote-app
cat > /etc/rsyslog.d/10-remote-local0-tls.conf <<'ANTRIEB_RSYSLOG'
# TLS-only receiver for local0 application messages from the three senders.
global(
    DefaultNetstreamDriverCAFile="/etc/pki/rsyslog/ca.crt"
    DefaultNetstreamDriverCertFile="/etc/pki/rsyslog/server.crt"
    DefaultNetstreamDriverKeyFile="/etc/pki/rsyslog/server.key"
)

module(
    load="imtcp"
    StreamDriver.Name="gtls"
    StreamDriver.Mode="1"
    StreamDriver.AuthMode="anon"
)

ruleset(name="remote_local0") {
    if ($syslogfacility-text == "local0") then {
        if ($fromhost-ip == "10.100.15.10") then {
            action(type="omfile" file="/var/log/remote-app/node1-local0.log" fileCreateMode="0640")
            stop
        }
        if ($fromhost-ip == "10.100.15.11") then {
            action(type="omfile" file="/var/log/remote-app/node2-local0.log" fileCreateMode="0640")
            stop
        }
        if ($fromhost-ip == "10.100.15.12") then {
            action(type="omfile" file="/var/log/remote-app/node3-local0.log" fileCreateMode="0640")
            stop
        }
    }
    stop
}

input(type="imtcp" port="6514" ruleset="remote_local0")
ANTRIEB_RSYSLOG
chmod 0644 /etc/rsyslog.d/10-remote-local0-tls.conf
restorecon /etc/rsyslog.d/10-remote-local0-tls.conf

